if __name__ == "__main__":
    root = Path(__file__).resolve().parents[1] / "Core/Sources/OpenAnkiCore/Resources"
    for language in ("en", "zh-Hans"):
        path = root / f"{language}.lproj/Localizable.strings"
        path.parent.mkdir(parents=True, exist_ok=True)
        lines = [f"{json.dumps(key, ensure_ascii=False)} = {json.dumps(value if language == 'en' else key, ensure_ascii=False)};" for key, value in sorted(STRINGS.items())]
        path.write_text("\n".join(lines) + "\n")
